+fn selected_text_from_rows(
+    rows: &[String],
+    selection: &VisualSelection,
+    intent: VisualCopyIntent,
+) -> String {
+    let kind = match intent {
+        VisualCopyIntent::Selection => selection.kind,
+        VisualCopyIntent::Line => VisualKind::Line,
+    };
+    let start_row = selection.anchor.row.min(selection.cursor.row);
+    let end_row = selection.anchor.row.max(selection.cursor.row);
+    let mut selected = Vec::new();
+    for row in start_row..=end_row {
+        let Some(line) = rows.get(row) else {
+            continue;
+        };
+        match kind {
+            VisualKind::Line => selected.push(line.clone()),
+            VisualKind::Block => {
+                let start_column = selection.anchor.column.min(selection.cursor.column);
+                let end_column = selection.anchor.column.max(selection.cursor.column) + 1;
+                selected.push(slice_chars(line, start_column, end_column));
+            }
+            VisualKind::Character => {
+                let row_len = line.chars().count();
+                let Some((start, end)) = selected_character_columns(
+                    selection,
+                    row,
+                    row_len,
+                    row_len,
+                ) else {
+                    continue;
+                };
+                selected.push(slice_chars(line, start, end));
+            }
+        }
+    }
+    selected.join("\n")
+}
+
+fn selected_column_range(
+    selection: &VisualSelection,
+    row: usize,
+    row_width: usize,
+    pane_width: usize,
+) -> Option<(usize, usize)> {
+    match selection.kind {
+        VisualKind::Line => {
+            let start_row = selection.anchor.row.min(selection.cursor.row);
+            let end_row = selection.anchor.row.max(selection.cursor.row);
+            (start_row <= row && row <= end_row).then_some((0, pane_width))
+        }
+        VisualKind::Block => {
+            let start_row = selection.anchor.row.min(selection.cursor.row);
+            let end_row = selection.anchor.row.max(selection.cursor.row);
+            if row < start_row || row > end_row {
+                return None;
+            }
+            let start_column = selection.anchor.column.min(selection.cursor.column);
+            let end_column = selection.anchor.column.max(selection.cursor.column) + 1;
+            (start_column < pane_width).then_some((start_column, end_column.min(pane_width)))
+        }
+        VisualKind::Character => selected_character_columns(selection, row, row_width, pane_width),
+    }
+}
+
+fn selected_character_columns(
+    selection: &VisualSelection,
+    row: usize,
+    row_width: usize,
+    pane_width: usize,
+) -> Option<(usize, usize)> {
+    let start_row = selection.anchor.row.min(selection.cursor.row);
+    let end_row = selection.anchor.row.max(selection.cursor.row);
+    if row < start_row || row > end_row || row_width == 0 {
+        return None;
+    }
+
+    let anchor_before_cursor = (selection.anchor.row, selection.anchor.column)
+        <= (selection.cursor.row, selection.cursor.column);
+    let (start_column, end_column) = if start_row == end_row {
+        (
+            selection.anchor.column.min(selection.cursor.column),
+            selection.anchor.column.max(selection.cursor.column) + 1,
+        )
+    } else if row == start_row {
+        let first_column = if anchor_before_cursor {
+            selection.anchor.column
+        } else {
+            selection.cursor.column
+        };
+        (first_column, row_width)
+    } else if row == end_row {
+        let last_column = if anchor_before_cursor {
+            selection.cursor.column
+        } else {
+            selection.anchor.column
+        };
+        (0, last_column + 1)
+    } else {
+        (0, row_width)
+    };
+
+    let start_column = start_column.min(pane_width).min(row_width);
+    let end_column = end_column.min(pane_width).min(row_width);
+    (start_column < end_column).then_some((start_column, end_column))
+}
+
+fn slice_chars(text: &str, start: usize, end: usize) -> String {
+    text.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn wrapped_rows(content: &str, width: u16, height: usize) -> Vec<String> {
+    let width = usize::from(width.max(1));
+    let mut rows = Vec::new();
+    for line in content.lines() {
+        if line.is_empty() {
+            rows.push(String::new());
+            continue;
+        }
+        let chars = line.chars().collect::<Vec<_>>();
+        for chunk in chars.chunks(width) {
+            rows.push(chunk.iter().collect());
+        }
+    }
+    if content.is_empty() {
+        rows.push(String::new());
+    }
+    rows.truncate(height);
+    rows
+}
